// Step 1: tidy the fields and check that the details needed to understand the request are there.
const clean = (v) => (v == null ? '' : String(v).trim().replace(/\s+/g, ' '));
const emailPattern = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

return $input.all().map(({ json }) => {
  const email = clean(json.email).toLowerCase();
  const usableEmail = emailPattern.test(email) ? email : '';
  const phone = clean(json.phone).replace(/[^\d+]/g, '');
  const length = parseFloat(clean(json.length_m).replace(/[^\d.]/g, ''));

  const request = {
    request_id: clean(json.request_id),
    received_at: clean(json.received_at),
    vessel: {
      name: clean(json.vessel_name),
      type: clean(json.vessel_type) || 'not given',
      length_m: length > 0 && length < 200 ? length : null,
    },
    contact: { name: clean(json.contact_name), email: usableEmail, phone },
    location: clean(json.location),
    requested_work: clean(json.requested_work),
    target_window: clean(json.target_window),
    client_deadline: clean(json.deadline),
    notes: clean(json.notes),
  };

  const missing = [];
  if (!request.contact.name) missing.push('contact name');
  if (!usableEmail && !phone) missing.push('email or phone');
  if (!request.vessel.name) missing.push('vessel name');
  if (request.vessel.length_m === null) missing.push('vessel length');
  if (!request.location) missing.push('where the vessel is');
  if (!request.requested_work) missing.push('description of the work');
  if (!request.target_window) missing.push('preferred time window');

  return { json: { request, missing_fields: missing, is_complete: missing.length === 0 } };
});

// Step 2: sort the request into broad project types and a time-sensitivity flag.
// Plain keyword rules, NOT AI. The output shows exactly which words matched, so a reviewer
// can see why. A request can match several types. Edit the lists to change the behavior.
const TYPE_RULES = [
  { type: 'Interior and joinery', keywords: ['interior', 'upholstery', 'carpet', 'cabin', 'salon', 'galley', 'joinery', 'curtain', 'furniture'] },
  { type: 'Exterior and finish', keywords: ['paint', 'hull', 'varnish', 'teak', 'deck', 'gelcoat', 'topside'] },
  { type: 'Mechanical and systems', keywords: ['engine', 'generator', 'hvac', 'air conditioning', 'pump', 'plumbing', 'electrical', 'stabiliz'] },
  { type: 'Electronics and navigation', keywords: ['radar', 'chartplotter', 'navigation', 'wifi', 'wi-fi', 'antenna', 'audio', 'camera'] },
];
const URGENT_WORDS = ['urgent', 'asap', 'deadline', 'charter season', 'before the season', 'hard stop'];

const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const matches = (text, keyword) => new RegExp('\\b' + escape(keyword), 'i').test(text);

return $input.all().map(({ json }) => {
  const r = json.request;
  const text = [r.requested_work, r.notes].join(' ');

  const project_types = TYPE_RULES
    .map((rule) => ({ type: rule.type, matched_keywords: rule.keywords.filter((k) => matches(text, k)) }))
    .filter((t) => t.matched_keywords.length);

  const urgency_reasons = [];
  if (r.client_deadline) urgency_reasons.push('client gave a finish-by condition: "' + r.client_deadline + '"');
  const hits = URGENT_WORDS.filter((k) => matches(text + ' ' + r.client_deadline, k));
  if (hits.length) urgency_reasons.push('words in the request: ' + hits.join(', '));

  return {
    json: {
      ...json,
      classification: {
        project_types: project_types.length ? project_types : [{ type: 'Needs scoping', matched_keywords: [] }],
        urgency: urgency_reasons.length ? 'Time-sensitive' : 'Planned',
        urgency_reasons,
        rule_note: 'Keyword rules only. Urgency here means the CLIENT said it matters. It is not a schedule or a commitment.',
      },
    },
  };
});

// Step 3: build a short project summary and a checklist of intake steps.
// Everything here is about organizing information. It does not estimate cost, pick vendors,
// approve work, or promise a timeline.
const STEP_BY_TYPE = {
  'Interior and joinery': 'Ask the client for photos or drawings of the areas involved',
  'Exterior and finish': 'Ask whether the client has records of the current finish',
  'Mechanical and systems': 'Ask for the equipment list and any recent service records',
  'Electronics and navigation': 'Ask which equipment is installed today',
  'Needs scoping': 'Set up a short call to understand what the client has in mind',
};

return $input.all().map(({ json }) => {
  const { request: r, missing_fields, classification } = json;
  const types = classification.project_types.map((t) => t.type);
  const vessel = [r.vessel.name || '(vessel name missing)', r.vessel.length_m ? r.vessel.length_m + ' m' : null, r.vessel.type !== 'not given' ? r.vessel.type.toLowerCase() : null].filter(Boolean);

  const next_steps = [
    { step: 'Read this summary against the original message and fix anything that is wrong', owner: 'Intake coordinator' },
    ...types.map((t) => ({ step: STEP_BY_TYPE[t], owner: 'Intake coordinator' })),
  ];
  if (missing_fields.length) next_steps.push({ step: 'Get the missing details: ' + missing_fields.join(', '), owner: 'Intake coordinator' });
  if (classification.urgency === 'Time-sensitive') next_steps.push({ step: 'Show the client-stated deadline to the project lead for their judgment', owner: 'Project lead' });
  next_steps.push({ step: 'Review and edit the draft status update before anything is sent', owner: 'Intake coordinator' });
  next_steps.push({ step: 'Decide the next move: scoping call, site visit, or not a fit', owner: 'Project lead' });

  return {
    json: {
      ...json,
      project_summary: {
        headline: vessel.join(', ') + ' | ' + types.join(' + ') + ' | ' + classification.urgency,
        vessel: r.vessel,
        where: r.location || 'not given',
        client_words: r.requested_work || 'not given',
        project_types: types,
        urgency: classification.urgency,
        client_stated_window: r.target_window || 'not given',
        open_questions: missing_fields,
      },
      next_steps: next_steps.map((s) => ({ ...s, done: false })),
    },
  };
});

// Step 4a: the intake is complete. Fill a status-update TEMPLATE for a person to review.
const SIGNOFF = ['Thank you,', '[Reviewer name]', 'Example Refit Coordination (fictional)'];
const reach = (c) => (c.email ? { channel: 'email', to: c.email } : { channel: 'phone call', to: c.phone });

return $input.all().map(({ json }) => {
  const { request: r, project_summary: s } = json;
  const first = r.contact.name.split(' ')[0];
  const body = [
    'Hello ' + first + ',',
    '',
    'Thank you for sending the details for ' + r.vessel.name + '. Here is what we understood:',
    '',
    '- Where the vessel is: ' + s.where,
    '- What you described: ' + s.client_words,
    '- Your preferred window: ' + s.client_stated_window,
    '',
    'If anything above is wrong, please tell us and we will correct it. Someone on the team will read your request and follow up with the next step.',
    '',
    'This message is an acknowledgment only. It is not a quote, a schedule, or an approval of any work.',
    '',
    ...SIGNOFF,
  ].join('\n');
  return { json: { ...json, draft_status_update: { ...reach(r.contact), subject: 'We received your request for ' + r.vessel.name, body, kind: 'acknowledgment (template)' } } };
});

// Step 4b: something is missing. Draft a short note asking for exactly that, for a person to review.
const SIGNOFF = ['Thank you,', '[Reviewer name]', 'Example Refit Coordination (fictional)'];
const QUESTION = {
  'contact name': 'the best name to use',
  'email or phone': 'the best email or phone to reach you',
  'vessel name': 'the name of the vessel',
  'vessel length': 'the approximate length of the vessel',
  'where the vessel is': 'where the vessel is located',
  'description of the work': 'a few lines about the work you have in mind',
  'preferred time window': 'the time window you are hoping for (an approximate season is fine)',
};

return $input.all().map(({ json }) => {
  const { request: r, missing_fields } = json;
  const canReply = Boolean(r.contact.email || r.contact.phone);
  const first = r.contact.name ? r.contact.name.split(' ')[0] : 'there';
  const body = [
    'Hello ' + first + ',',
    '',
    'Thank you for getting in touch about ' + (r.vessel.name || 'your vessel') + '. To organize your request, could you send:',
    '',
    ...missing_fields.map((f) => '- ' + QUESTION[f]),
    '',
    'This message is an acknowledgment only. It is not a quote, a schedule, or an approval of any work.',
    '',
    ...SIGNOFF,
  ].join('\n');
  const draft = canReply
    ? { channel: r.contact.email ? 'email' : 'phone call', to: r.contact.email || r.contact.phone, subject: 'A few questions about your request', body, kind: 'missing-details request (template)' }
    : { channel: 'none', to: '', subject: '', body: 'No reply is possible: no usable email or phone. Check the original source for another way to reach the client.', kind: 'internal note, no reply drafted' };
  return { json: { ...json, draft_status_update: draft } };
});

// Step 6: one readable record per request. Read `summary` first, then the sections in order:
// intake, checks, categorization, project summary, next steps, draft status update, approval.
return $input.all().map(({ json }) => {
  const { request, missing_fields, classification, project_summary, next_steps, draft_status_update, approval } = json;
  const summary = [
    request.request_id,
    request.vessel.name || '(no vessel name)',
    classification.project_types.map((t) => t.type).join(' + '),
    classification.urgency,
    missing_fields.length ? 'MISSING: ' + missing_fields.join(', ') : 'complete',
    approval.status,
    'message sent: ' + (approval.message_sent ? 'YES' : 'no'),
  ].join(' | ');

  return {
    json: {
      summary,
      intake: request,
      checks: { is_complete: missing_fields.length === 0, missing_fields },
      categorization: classification,
      project_summary,
      next_steps,
      draft_status_update,
      not_done_by_this_workflow: ['cost estimate', 'vendor selection', 'timeline promise', 'approval of work', 'sending any message'],
      approval,
    },
  };
});
